// Content carried over from the old WordPress site (garimaschool.com).
// Generated by scripts/import-old-site.py — re-run that script instead of
// editing the JSON by hand.
//
// - SEO_LANDING_PAGES: footer "Best School in ..." pages + policy pages, served
//   at their old URLs by src/app/[slug]/page.tsx.
// - BLOG_SEED: the old site's blog posts. They live in the `blogs` table now
//   (admin → Articles / Blogs); this file only seeds an empty table and is the
//   fallback when the DB is down (see src/lib/blogs.ts).

import blogsData from '@/data/blogs.json';
import landingData from '@/data/seoLandingPages.json';

export type LegacyPage = {
  slug: string;
  title: string;
  seoTitle: string;
  metaDescription: string;
  image: string | null;
  html: string;
};

export type BlogPost = LegacyPage & {
  date: string;
  modified: string;
  excerpt: string;
};

export const BLOG_SEED = blogsData as BlogPost[];
export const SEO_LANDING_PAGES = landingData as LegacyPage[];

export function findLandingPage(slug: string): LegacyPage | undefined {
  return SEO_LANDING_PAGES.find((p) => p.slug === slug);
}

export function formatBlogDate(value: string): string {
  const [y, m, d] = value.split('-').map(Number);
  return new Date(y, m - 1, d).toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' });
}
